def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")
    width = observation.get("grid_width") or 1
    height = observation.get("grid_height") or 1

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    # Pursuit and evasion
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            dx, dy = move_towards(ox, oy)
            return [dx, dy]
        corners = [
            [0, 0],
            [0, height - 1],
            [width - 1, 0],
            [width - 1, height - 1],
        ]
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return move_towards(target[0], target[1])

    # Territory control
    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells") or
            observation.get("opponent_territory") or
            []
        )
        if targets:
            target_cell = min(targets, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
            return move_towards(target_cell[0], target_cell[1])
        else:
            return [0, 0]

    # Resource collection
    resources = observation.get("resources") or []
    if resources:
        best_res = min(resources, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(best_res[0], best_res[1])
    else:
        dx, dy = move_towards(ox, oy)
        return [dx, dy]

